if self.fork_tracker.is_shanghai_activated() {
    if let Err(err) = transaction.ensure_max_init_code_size(MAX_INIT_CODE_BYTE_SIZE) {
        return Err(TransactionValidationOutcome::Invalid(transaction, err))
    }
}

